type AuditManifestItem = {
  visualKey: string;
  familySlug: string;
  slug: string;
};

const auditItems = auditManifest.items as AuditManifestItem[];

function manifestIdentity(familySlug: string, slug: string, occurrence: number): string {
  return `${familySlug}\u0000${slug}\u0000${occurrence}`;
}

function buildManifestVisualKeyIndex(): Map<string, string> {
  const visualKeys = new Map<string, string>();
  const occurrences = new Map<string, number>();

  for (const item of auditItems) {
    const productIdentity = `${item.familySlug}\u0000${item.slug}`;
    const occurrence = (occurrences.get(productIdentity) ?? 0) + 1;
    const identity = manifestIdentity(item.familySlug, item.slug, occurrence);

    if (visualKeys.has(identity)) {
      throw new Error(`[productCatalog] Duplicate manifest product identity: ${identity}`);
    }

    occurrences.set(productIdentity, occurrence);
    visualKeys.set(identity, item.visualKey);
  }

  return visualKeys;
}

const manifestVisualKeys = buildManifestVisualKeyIndex();

function getVisualKey(familySlug: string, slug: string, occurrence: number): string {
  const identity = manifestIdentity(familySlug, slug, occurrence);
  const visualKey = manifestVisualKeys.get(identity);

  if (!visualKey) {
    throw new Error(`[productCatalog] Missing manifest visual key for ${identity}`);
  }

  return visualKey;
}

function normalizeProductCatalog(
  rawCatalog: Localized<RawProductCategoryFamily[]>,
): Localized<ProductCategoryFamily[]> {
  const normalized = {} as Localized<ProductCategoryFamily[]>;

  for (const lang of LANGS) {
    normalized[lang] = rawCatalog[lang].map((family) => {
      const occurrences = new Map<string, number>();

      return {
        slug: family.slug,
        products: family.products.map((product) => {
          const occurrence = (occurrences.get(product.slug) ?? 0) + 1;
          const visualKey = getVisualKey(family.slug, product.slug, occurrence);

          occurrences.set(product.slug, occurrence);

          return {
            ...product,
            visualKey,
            permalink: occurrence > 1 ? `${product.slug}-${occurrence}` : product.slug,
            media: buildProductMedia({
              visualKey,
              alt: product.alt,
              heroImage: product.heroImage,
              galleryImages: product.galleryImages,
            }),
          };
        }),
      };
    });
  }

  return normalized;
}

export const productCatalogContent = normalizeProductCatalog(rawProductCatalogContent);
